const fn = new Function(code + "\nreturn { parseCommit };");
const { parseCommit } = fn();
const p = parseCommit("feat(auth): add password reset");
if (p.type !== "feat" || p.scope !== "auth" || p.breaking !== false || p.desc !== "add password reset") throw new Error("Full form parsed.");
const q = parseCommit("docs: update guide");
if (q.type !== "docs" || q.scope !== null) throw new Error("Scope-less form: scope is null.");

const fn = new Function(code + "\nreturn { parseCommit };");
const { parseCommit } = fn();
if (parseCommit("feat!: new api").breaking !== true) throw new Error("! marks breaking.");
if (parseCommit("fix: x\n\nBREAKING CHANGE: y").breaking !== true) throw new Error("Footer marks breaking.");
if (parseCommit("fix: normal")?.breaking !== false) throw new Error("Normal commits are not breaking.");

const fn = new Function(code + "\nreturn { parseCommit };");
const { parseCommit } = fn();
if (parseCommit("updated stuff") !== null) throw new Error("No type, no colon.");
if (parseCommit("feat") !== null) throw new Error("Type alone is not a commit.");
if (parseCommit("feat:" ) !== null) throw new Error("Empty description.");
if (parseCommit("blah: desc") !== null) throw new Error("Unknown type => null.");
